#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn example() {
        let root = node(3, leaf(9), node(20, leaf(15), leaf(7)));
        assert_eq!(tree_height(&root), 3);
    }

    #[test]
    fn empty() {
        assert_eq!(tree_height(&None), 0);
    }

    #[test]
    fn single() {
        assert_eq!(tree_height(&leaf(1)), 1);
    }

    #[test]
    fn lopsided() {
        let root = node(1, None, node(2, node(3, None, leaf(4)), None));
        assert_eq!(tree_height(&root), 4);
    }

    #[test]
    fn deep_chain() {
        let mut root = None;
        for i in 0..500 {
            root = node(i, root, None);
        }
        assert_eq!(tree_height(&root), 500);
    }
}
